"use client";
import { useRef } from "react";
import {
  useScrollMotion,
  type ScrollMotionProps,
  type ScrollEntranceOptions,
} from "./scroll-shared";
import { scrollEase, scrollStagger } from "./scroll-math";
export interface CounterProps extends ScrollMotionProps, ScrollEntranceOptions {
  value: number;
  from?: number;
  decimals?: number;
  prefix?: string;
  suffix?: string;
  variant?: "count" | "rolling";
  stagger?: number;
  format?: (value: number) => string;
}
export function Counter({
  value,
  from = 0,
  decimals = 0,
  prefix = "",
  suffix = "",
  variant = "count",
  stagger = 0.25,
  format,
  trigger = "enter",
  ...props
}: CounterProps) {
  const root = useRef<HTMLSpanElement>(null),
    digits = Math.max(0, Math.min(10, Math.floor(decimals))),
    target = Number.isFinite(value) ? value : 0,
    initial = Number.isFinite(from) ? from : 0;
  const display = (v: number) => (format ? format(v) : v.toFixed(digits)),
    final = display(target);
  const startingDigits = display(initial)
    .replace(/\D/g, "")
    .padStart(final.replace(/\D/g, "").length, "0")
    .slice(-final.replace(/\D/g, "").length);
  useScrollMotion(
    root,
    { ...props, trigger },
    ({ progress: p }) => {
      const el = root.current!,
        current = initial + (target - initial) * scrollEase(p);
      el.dataset.value = String(current);
      if (variant === "count")
        el.querySelector<HTMLElement>("[data-scroll-count]")!.textContent = display(current);
      else {
        const columns = el.querySelectorAll<HTMLElement>("[data-scroll-digit]");
        columns.forEach((col, i) => {
          const digit = Number(col.dataset.scrollDigit),
            q = scrollEase(scrollStagger(p, i, columns.length, stagger)),
            startDigit = Number(startingDigits[i] ?? 0);
          col.style.transform = `translateY(${(-(startDigit + (10 + digit - startDigit) * q) * 100) / 20}%)`;
        });
      }
    },
    `${target}:${initial}:${digits}:${prefix}:${suffix}:${variant}:${stagger}:${final}`,
  );
  return (
    <span
      ref={root}
      data-scroll-animation="counter"
      className={props.className}
      aria-label={`${prefix}${final}${suffix}`}
      style={{
        display: "inline-flex",
        alignItems: "baseline",
        fontVariantNumeric: "tabular-nums",
        whiteSpace: "nowrap",
        ...props.style,
      }}
    >
      <span aria-hidden="true">{prefix}</span>
      {variant === "count" ? (
        <span data-scroll-count="" aria-hidden="true">
          {final}
        </span>
      ) : (
        <span
          aria-hidden="true"
          style={{ display: "inline-flex", height: "1em", lineHeight: 1, overflow: "hidden" }}
        >
          {[...final].map((char, i) =>
            /\d/.test(char) ? (
              <span
                key={i}
                style={{
                  display: "inline-block",
                  width: ".65em",
                  height: "1em",
                  overflow: "hidden",
                }}
              >
                <span
                  data-scroll-digit={char}
                  style={{
                    display: "flex",
                    flexDirection: "column",
                    transform: `translateY(${-(10 + Number(char)) * 5}%)`,
                  }}
                >
                  {Array.from({ length: 20 }, (_, j) => (
                    <span key={j} style={{ height: "1em", flexShrink: 0, textAlign: "center" }}>
                      {j % 10}
                    </span>
                  ))}
                </span>
              </span>
            ) : (
              <span key={i}>{char}</span>
            ),
          )}
        </span>
      )}
      <span aria-hidden="true">{suffix}</span>
    </span>
  );
}
